def solve(n: int, d: int) -> int:
    result = n // d
    remainder = n % d

    if remainder * 2 > d:
        return result + (1 if n >= 0 else -1)
    elif remainder * 2 == d:
        return result + (1 if n >= 0 else -1)

    return result

def solve(n: int, d: int) -> int:
    remainder = n % d
    half_d = d // 2

    if remainder < half_d:
        return n // d
    elif remainder > half_d:
        return n // d + 1 if n >= 0 else n // d - 1
    else:  # exactly halfway
        return n // d + (1 if n >= 0 else -1)

