def solve(text: str) -> str:
    """Split text on Unicode whitespace and return the longest word.
    Ties go to the first word. Return empty string when there are no words.
    Punctuation remains part of a word.
    """
    words = text.split()
    if not words:
        return ""

    longest = words[0]
    for word in words[1:]:
        if len(word) > len(longest):
            longest = word
    return longest

