        if token.startswith('-'):
            sign = -1
            token = token[1:]
        else:
            sign = 1

        if '_' in token:
            parts = token.split('_')
            whole = int(parts[0])
            frac_part = parts[1]
        else:
            whole = 0
            frac_part = token

        if '/' in frac_part:
            num, den = map(int, frac_part.split('/'))
            result = Fraction(whole * den + num, den)
        else:
            result = Fraction(whole, 1)

        return result * sign

    def apply_operator(left: Fraction, right: Fraction, op: str) -> Fraction:
        if op == '+':
            return left + right
        elif op == '-':
            return left - right
        elif op == '*':
            return left * right
        elif op == '/':
            if right == 0:
                raise ZeroDivisionError
            return left / right
        else:
            raise ValueError(f"Unknown operator: {op}")

    def evaluate(tokens: list) -> Fraction:
        for i in range(len(tokens) - 1, 0, -2):
            op = tokens[i]
            if op in ('*', '/'):
                result = apply_operator(tokens[i-1], tokens[i+1], op)
                tokens[i-1:i+2] = [result]

        for i in range(len(tokens) - 1, 0, -2):
            op = tokens[i]
            if op in ('+', '-'):
                result = apply_operator(tokens[i-1], tokens[i+1], op)
                tokens[i-1:i+2] = [result]

        return tokens[0]

    def format_result(frac: Fraction) -> str:
        if frac == 0:
            return "0"

        result = abs(frac)
        sign = "-" if frac < 0 else ""

