        remainder = result - whole

        if remainder == 0:
            return f"{sign}{whole}"

        if whole == 0:
            return f"{sign}{remainder.numerator}/{remainder.denominator}"

        return f"{sign}{whole}_{remainder.numerator}/{remainder.denominator}"

    tokens = expression.strip().split()
    parsed = []

    for i, token in enumerate(tokens):
        if i % 2 == 0:
            parsed.append(parse_operand(token))
        else:
            parsed.append(token)

    try:
        result = evaluate(parsed)
        return format_result(result)
    except ZeroDivisionError:
        return "undefined"

