        sign = -1
        token = token[1:]

    if '_' in token:
        whole_str, frac_str = token.split('_', 1)
        whole = int(whole_str) if whole_str else 0
        num_str, denom_str = frac_str.split('/', 1)
        num = int(num_str)
        denom = int(denom_str)
        return Fraction(whole * denom + num, denom) * sign
    elif '/' in token:
        num_str, denom_str = token.split('/', 1)
        return Fraction(int(num_str), int(denom_str)) * sign
    else:
        return Fraction(int(token), 1) * sign

