    """Evaluate rational expression and return result as mixed number."""
    tokens = expression.strip().split()

    # First pass: parse operands and convert to Fractions
    parsed_tokens = []
    for i, token in enumerate(tokens):
        if i % 2 == 0:  # operand
            parsed_tokens.append(_parse_operand(token))
        else:  # operator
            parsed_tokens.append(token)

    # Second pass: handle * and / with left associativity
    i = 1
    while i < len(parsed_tokens):
        if parsed_tokens[i] in ('*', '/'):
            op = parsed_tokens[i]
            left = parsed_tokens[i - 1]
            right = parsed_tokens[i + 1]

            if op == '/' and right == 0:
                return "undefined"

            if op == '*':
                result = left * right
            else:
                result = left / right

            parsed_tokens[i - 1:i + 2] = [result]
            i -= 1
        else:
            i += 2

    # Third pass: handle + and - with left associativity
    result = parsed_tokens[0]
    i = 1
    while i < len(parsed_tokens):
        op = parsed_tokens[i]
        right = parsed_tokens[i + 1]

        if op == '+':
            result += right
        else:  # '-'
            result -= right

        i += 2

    # Format the result
    if result.denominator == 1:
        return str(result.numerator)

    if abs(result) < 1:
        return f"{abs(result.numerator)}/{result.denominator}" if result >= 0 else f"-{abs(result.numerator)}/{result.denominator}"

    whole = abs(result) // result.denominator
    remainder = abs(result) % result.denominator

    if remainder == 0:
        return str(whole if result >= 0 else -whole)
    elif whole == 0:
        return f"{result.numerator}/{result.denominator}"
    else:
        return f"{whole}_{remainder}/{result.denominator}" if result >= 0 else f"-{whole}_{remainder}/{result.denominator}"

