        # Handle backslash escaping (only outside quotes)
        if char == '\\' and not (in_single or in_double):
            if i + 1 >= n:
                return None  # Backslash as last character
            backslash_pending = True
            i += 1
            char = line[i]

        # Single quote handling
        if char == "'":
            if backslash_pending:
                # If backslash is pending, it's literal inside single quotes
                pass
            if in_single:
                in_single = False
            else:
                in_single = True
            current_word.append(char)

        # Double quote handling
        elif char == '"':
            if backslash_pending:
                # Inside double quotes, handle specific escapes
                if i + 1 < n:
                    next_char = line[i + 1]
                    if next_char == '"' or next_char == '\\':
                        # Escaped quote or backslash becomes literal
                        current_word.append(char)
                        i += 1
                        char = line[i]
                    elif next_char == '$' or next_char == '`':
                        # Escaped $ or ` becomes literal
                        current_word.append(next_char)
                        i += 1
                        char = line[i]
                    else:
                        # Any other character after backslash stays as-is
                        current_word.append('\\')
                else:
                    # Backslash as last char in double quote context
                    return None
            else:
                if in_double:
                    in_double = False
                else:
                    in_double = True
                current_word.append(char)

        # Quote termination checks
        elif in_single and char == "'":
            return None  # Can't reach here due to above check
        elif in_double and char == '"' and not backslash_pending:
            in_double = False
            current_word.append(char)

        # Word boundary detection (only outside quotes)
        elif not (in_single or in_double) and (char == ' ' or char == '\t'):
            # Skip trailing spaces
            if current_word:
                # Start new word
                result.append(''.join(current_word))
                current_word = []
            # Skip all spaces/tabs
            while i < n and (line[i] == ' ' or line[i] == '\t'):
                i += 1
            continue

        # Regular character handling
        else:
            if backslash_pending:
                # Backslash was already processed, char is literal
                pass
            current_word.append(char)

        i += 1

    # Check for missing closing quotes
    if in_single or in_double:
        return None

    # Add last word if exists
    if current_word:
        result.append(''.join(current_word))

    return result

def solve(line: str) -> list[str] | None:
