                continue
            elif char == "'":
                # Start single-quoted section
                state = 'single-quoted'
                i += 1
                continue
            elif char == '"':
                # Start double-quoted section
                state = 'double-quoted'
                i += 1
                continue
            elif char in ' \t':
                # Space/tab separator outside quotes
                if current_word:
                    words.append(''.join(current_word))
                    current_word = []
                # Skip all consecutive spaces/tabs
                while i < n and line[i] in ' \t':
                    i += 1
                continue
            else:
                # Regular character
                current_word.append(char)
                i += 1

        elif state == 'single-quoted':
            if char == "'":
                # End single-quoted section
                words.append(''.join(current_word))
                current_word = []
                state = 'normal'
                i += 1
            else:
                # Literal inside single quotes
                current_word.append(char)
                i += 1

        elif state == 'double-quoted':
            if char == '\\':
                # Escaped character inside double quotes
                if i == n - 1:
                    return None  # Backslash as last character is error
                i += 1
                if i < n:
                    next_char = line[i]
                    if next_char in '\\"\`$':
                        current_word.append(next_char)
                    elif next_char == '\\':
                        current_word.append('\\\\')
                    elif next_char == '"':
                        current_word.append('\\"')
                    else:
                        current_word.append('\\\\' + next_char)
                    i += 1
                continue
            elif char == '"':
                # End double-quoted section
                if i > 0 and line[i-1] == '\\\\':
                    # Escaped quote doesn't close
                    current_word.append('"')
                    i += 1
                else:
                    words.append(''.join(current_word))
                    current_word = []
                    state = 'normal'
                    i += 1
            else:
                # Literal character inside double quotes
                current_word.append(char)
                i += 1

    # Add the last word if exists
    if current_word:
        words.append(''.join(current_word))

    return words

