    poly = poly.replace(" ", "")

    if not poly:
        return result

    # Parse the first term
    if poly[0] in '+-':
        sign = -1 if poly[0] == '-' else 1
        i = 1
    else:
        sign = 1
        i = 0

    while i < len(poly):
        # Find next term boundary
        j = i
        if j < len(poly) and poly[j] in '+-':
            j = poly.find(poly[j], i)

        term = poly[i:j]

        # Parse coefficient and exponent
        if 'x' not in term:
            coeff = int(term) if term else 1
            exp = 0
        else:
            x_idx = term.find('x')
            coeff_str = term[:x_idx]
            if coeff_str == '' or coeff_str == '+':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)

            exp_str = ''
            if x_idx + 1 < len(term) and term[x_idx+1] == '^':
                exp_str = term[x_idx+2:]

            if exp_str == '' or exp_str == '+':
                exp = 1
            elif exp_str == '-':
                exp = -1
            else:
                exp = int(exp_str)

        result[exp] = result.get(exp, 0) + sign * coeff

        # Move to next term
        if j < len(poly):
            sign = -1 if poly[j] == '-' else 1
            i = j + 1
        else:
            break

    return result


