from typing import List, Optional

def solve(rolls: List[int]) -> Optional[int]:
    def is_valid_roll(r: int) -> bool:
        return 0 <= r <= 10

    def is_strike(r: int) -> bool:
        return r == 10

    def is_spare(a: int, b: int) -> bool:
        return a + b == 10

    if not rolls:
        return None

    if not all(is_valid_roll(r) for r in rolls):
        return None

    i = 0
    total_score = 0
    frame_num = 1

    # Process frames 1-9
    while frame_num <= 9:
        if i >= len(rolls):
            return None

        if is_strike(rolls[i]):
            total_score += 10 + rolls[i+1] + rolls[i+2]
            i += 1
        else:
            if i + 1 >= len(rolls):
                return None
            frame_score = rolls[i] + rolls[i+1]
            if frame_score > 10:
                return None
            total_score += frame_score
            i += 2

        frame_num += 1

    # Process frame 10 with its special rules
    if frame_num == 10:
        if i >= len(rolls):
            return None

        if is_strike(rolls[i]):
            if i + 2 >= len(rolls):
                return None
            frame_score = 10 + rolls[i+1] + rolls[i+2]
            if i + 1 >= len(rolls):
                return None
            if is_strike(rolls[i+1]) and rolls[i+2] > 10:
                return None
            if not is_strike(rolls[i+1]) and rolls[i+1] + rolls[i+2] > 10:
                return None
        elif i + 1 >= len(rolls):
            return None
        else:
            frame_score = rolls[i] + rolls[i+1]
            if frame_score > 10:
                return None
            if is_spare(rolls[i], rolls[i+1]):
                if i + 2 >= len(rolls):
                    return None
                frame_score += rolls[i+2]
                if rolls[i+2] > 10:
                    return None
            else:
                if i + 2 < len(rolls):
                    return None
        total_score += frame_score

    # Check if we used all rolls (no extra after frame 10)
    return total_score if i == len(rolls) else None

def solve(rolls: list[int]) -> int | None:
    if not rolls:
        return None

    n = len(rolls)
    total_score = 0
    frame = 0
    roll_idx = 0

    while frame < 10 and roll_idx < n:
        frame_score = 0
        is_strike = False
        is_spare = False

        if rolls[roll_idx] == 10:
            frame_score = 10
            is_strike = True
            roll_idx += 1
        else:
            first_roll = rolls[roll_idx]
            frame_score += first_roll
            roll_idx += 1

            if roll_idx >= n:
                return None

            second_roll = rolls[roll_idx]

            if first_roll + second_roll == 10:
                is_spare = True
                frame_score += second_roll
            else:
                frame_score += second_roll

            roll_idx += 1

        if frame < 9:
            if is_strike:
                if roll_idx >= n:
                    return None
                frame_score += rolls[roll_idx]
                roll_idx += 1

                if roll_idx >= n:
                    return None
                frame_score += rolls[roll_idx]
                roll_idx += 1
            elif is_spare:
                if roll_idx >= n:
                    return None
                frame_score += rolls[roll_idx]
                roll_idx += 1
        else:
            if is_strike:
                if roll_idx >= n:
                    return None
                first_bonus = rolls[roll_idx]
                frame_score += first_bonus
                roll_idx += 1

                if first_bonus == 10 and roll_idx < n:
                    second_bonus = rolls[roll_idx]
                    frame_score += second_bonus
                    roll_idx += 1
                elif roll_idx < n:
                    second_bonus = rolls[roll_idx]
                    if first_bonus + second_bonus > 10:
                        return None
                    frame_score += second_bonus
                    roll_idx += 1
            elif is_spare:
                if roll_idx >= n:
