    return total_score

def solve(rolls: list[int]) -> int | None:
    if not rolls:
        return None

    # Validation
    roll_index = 0
    frame = 1
    total_rolls = len(rolls)

    while frame <= 9:
        if roll_index >= total_rolls:
            return None

        first = rolls[roll_index]
        if not 0 <= first <= 10:
            return None

        if first == 10:
            # Strike - use one roll
            roll_index += 1
        else:
            # Not a strike - need two rolls
            if roll_index + 1 >= total_rolls:
                return None

            second = rolls[roll_index + 1]
            if not 0 <= second <= 10:
                return None

            if first + second > 10:
                return None

            roll_index += 2

        frame += 1

    # Frame 10
    if roll_index >= total_rolls:
        return None

    first = rolls[roll_index]
    if not 0 <= first <= 10:
        return None

    if first == 10:
        # Strike in frame 10 - need 3 rolls
        if roll_index + 2 >= total_rolls:
            return None

        second = rolls[roll_index + 1]
        third = rolls[roll_index + 2]

        if not 0 <= second <= 10 or not 0 <= third <= 10:
            return None

        if second == 10:
            # Two strikes - third can be 0-10
            pass
        elif second + third > 10:
            return None
    else:
        # Not a strike
        if roll_index + 1 >= total_rolls:
            return None

        second = rolls[roll_index + 1]
        if not 0 <= second <= 10:
            return None

        frame_sum = first + second

        if frame_sum == 10:
            # Spare - need one more roll
            if roll_index + 2 >= total_rolls:
                return None

            third = rolls[roll_index + 2]
            if not 0 <= third <= 10:
                return None
        elif frame_sum > 10:
