                if left > right:
                    dp[i][j] = (dp[i+1][j-1] * 2 + 2) % MOD
                elif left == right:
                    dp[i][j] = (dp[i+1][j-1] * 2 + 1) % MOD
                else:
                    dp[i][j] = (dp[i+1][j-1] * 2 - dp[left+1][right-1]) % MOD

    return dp[0][n-1] % MOD

