def solve(text: str) -> int:
    MOD = 1_000_000_007
    n = len(text)
    if n == 0:
        return 0

    # dp[i][j] = number of distinct palindromic subsequences in text[i:j+1]
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if text[i] != text[j]:
                dp[i][j] = dp[i+1][j] + dp[i][j-1] - dp[i+1][j-1]
            else:
                # Find first occurrence of text[i] in (i, j)
                left = i + 1
                while left < j and text[left] != text[i]:
                    left += 1

                # Find last occurrence of text[i] in (i, j)
                right = j - 1
                while right > i and text[right] != text[i]:
                    right -= 1

                if left > right:
                    dp[i][j] = 2 * dp[i+1][j-1] + 2
                elif left == right:
                    dp[i][j] = 2 * dp[i+1][j-1] + 1
                else:
                    dp[i][j] = 2 * dp[i+1][j-1] - dp[left+1][right-1]

            # Ensure result is positive (mod arithmetic)
            dp[i][j] %= MOD
            if dp[i][j] < 0:
                dp[i][j] += MOD

    return dp[0][n-1]

