def solve(amount: int, coins: list[int]) -> int:
    if amount == 0:
        return 0

    # Use amount + 1 as "infinity" - impossible value
    # because max coins needed would be amount (all 1s)
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0

    for i in range(1, amount + 1):
        for coin in coins:
            if coin <= i:
                dp[i] = min(dp[i], dp[i - coin] + 1)

