def solve(n: int, edges: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []

    parent = list(range(n))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        px, py = find(x), find(y)
        if px != py:
            parent[py] = px

    for u, v in edges:
        if u != v:
            union(u, v)

    sizes = {}
    for i in range(n):
        root = find(i)
        sizes[root] = sizes.get(root, 0) + 1

    return sorted(sizes.values())

def solve(n: int, edges: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []

    adj = [[] for _ in range(n)]
    for u, v in edges:
        if u != v:
            adj[u].append(v)
            adj[v].append(u)

    visited = [False] * n
    component_sizes = []

    def dfs(node):
        visited[node] = True
        size = 1
        for neighbor in adj[node]:
            if not visited[neighbor]:
                size += dfs(neighbor)
        return size

    for i in range(n):
