def solve(values: list[int]) -> int:
    if not values:
        return 0

    tails = []

    for num in values:
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid

        if left == len(tails):
            tails.append(num)
