        curr[0] = i
        for j, right_char in enumerate(right, 1):
            if left_char == right_char:
                curr[j] = prev[j-1]
            else:
                curr[j] = 1 + min(prev[j], curr[j-1], prev[j-1])
        prev, curr = curr, prev

    return prev[len(right)]

