def solve(intervals: list[tuple[int, int]]) -> int:
    if len(intervals) < 2:
        return 0

    # Sort by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    result = 0
    active_intervals = []

    for start, end in sorted_intervals:
        # Remove intervals that have already ended
        while active_intervals and active_intervals[0][1] <= start:
            active_intervals.pop(0)

        # Count overlapping intervals with positive overlap
        for act_start, act_end in active_intervals:
            overlap_start = max(start, act_start)
            overlap_end = min(end, act_end)
            if overlap_start < overlap_end:
                result += 1

        # Add current interval to active list
        active_intervals.append((start, end))

    return result

