def solve(expression: str) -> int:
    tokens = list(tokenize(expression))

    def parse_expression(pos):
        value, pos = parse_term(pos)
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right, pos = parse_term(pos)
            if op == '+':
                value += right
            else:
                value -= right
        return value, pos

    def parse_term(pos):
        value, pos = parse_factor(pos)
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            right, pos = parse_factor(pos)
            if op == '*':
                value *= right
            else:
                if right == 0:
                    raise ValueError("Division by zero")
                if value * right < 0 and value % right != 0:
                    value = value // right + 1
                else:
                    value //= right
        return value, pos

    def parse_factor(pos):
        return parse_unary(pos)

    def parse_unary(pos):
        if pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            value, pos = parse_unary(pos)
            return -value if op == '-' else value, pos
        return parse_primary(pos)

    def parse_primary(pos):
        if tokens[pos] == '(':
            value, pos = parse_expression(pos + 1)
            if pos >= len(tokens) or tokens[pos] != ')':
                raise ValueError("Mismatched parentheses")
            return value, pos + 1
        elif tokens[pos].lstrip('-').isdigit():
            num = int(tokens[pos])
            return num, pos + 1
        else:
            raise ValueError(f"Unexpected token: {tokens[pos]}")

    def tokenize(expr):
        i = 0
        while i < len(expr):
            if expr[i].isspace():
                i += 1
                continue
            if expr[i] in '()+-*/':
                yield expr[i]
                i += 1
                continue
            if expr[i] == '-':
                if i + 1 < len(expr) and expr[i+1].isdigit():
                    start = i
                    i += 1
                    while i < len(expr) and expr[i].isdigit():
                        i += 1
                    yield expr[start:i]
                    continue
                else:
                    yield '-'
                    i += 1
                    continue
            if expr[i].isdigit():
                start = i
                i += 1
                while i < len(expr) and expr[i].isdigit():
                    i += 1
                yield expr[start:i]
                continue
