    # Tokenize
    tokens = []
    i = 0
    n = len(expression)

    while i < n:
        ch = expression[i]

        if ch.isspace():
            i += 1
            continue

        if ch.isdigit():
            num = 0
            while i < n and expression[i].isdigit():
                num = num * 10 + int(expression[i])
                i += 1
            tokens.append(num)
            continue

        if ch in '()':
            tokens.append(ch)
            i += 1
            continue

        if ch in '+-*/':
            tokens.append(ch)
            i += 1
            continue

        i += 1

    # Parse with recursive descent
    idx = [0]

    def parse_expression():
        left = parse_term()
        while idx[0] < len(tokens) and tokens[idx[0]] in '+-':
            op = tokens[idx[0]]
            idx[0] += 1
            right = parse_term()
            left = left + right if op == '+' else left - right
        return left

    def parse_term():
        left = parse_factor()
        while idx[0] < len(tokens) and tokens[idx[0]] in '*/':
            op = tokens[idx[0]]
            idx[0] += 1
            right = parse_factor()
            if op == '*':
                left = left * right
            else:
                left = int(left / right)
        return left

    def parse_factor():
        if tokens[idx[0]] == '(':
            idx[0] += 1
            value = parse_expression()
            idx[0] += 1  # Skip ')'
            return value

        # Handle unary operators
        if tokens[idx[0]] == '+':
            idx[0] += 1
            return parse_factor()
        elif tokens[idx[0]] == '-':
            idx[0] += 1
            return -parse_factor()

        # Must be a number
        val = tokens[idx[0]]
        idx[0] += 1
        return val

    return parse_expression()

def solve(expression: str) -> int:
    # Tokenize the expression
    tokens = []
    i = 0
    n = len(expression)

    while i < n:
        if expression[i].isspace():
            i += 1
            continue

        if expression[i] in '+-*/()':
            # Check for unary minus or plus
            if expression[i] in '+-' and (i == 0 or expression[i-1] in '(+-*/'):
                # Unary operator handling
                sign = 1
                # Process multiple unary signs
                while i < n and expression[i] in '+-':
                    if expression[i] == '-':
                        sign *= -1
                    i += 1
                    # Skip whitespace after unary
                    while i < n and expression[i].isspace():
                        i += 1

                # Process the following number or parenthesized expression
                if i < n and expression[i] == '(':
                    # Find matching closing parenthesis
                    depth = 1
                    start = i + 1
                    i += 1
                    while i < n and depth > 0:
                        if expression[i] == '(':
                            depth += 1
                        elif expression[i] == ')':
                            depth -= 1
                        i += 1
                    # Extract and evaluate inner expression
                    inner_expr = expression[start:i-1]
                    val = solve(inner_expr)
                    tokens.append(str(val * sign))
                elif i < n and (expression[i].isdigit() or expression[i] == '0'):
                    # Parse number
                    start = i
                    while i < n and expression[i].isdigit():
                        i += 1
                    num_str = expression[start:i]
                    tokens.append(str(int(num_str) * sign))
                else:
                    raise ValueError("Invalid expression")
            else:
                # Binary operator
                tokens.append(expression[i])
                i += 1
        elif expression[i].isdigit():
            # Parse number
            start = i
            while i < n and expression[i].isdigit():
                i += 1
            num_str = expression[start:i]
            # Check for invalid leading zero
            if num_str != '0' and num_str.startswith('0'):
                raise ValueError("Invalid expression: leading zero")
            tokens.append(num_str)
        else:
            raise ValueError(f"Invalid character: {expression[i]}")

    # Shunting yard algorithm to convert to postfix
    output = []
    ops = []

    def precedence(op):
        if op in '+-':
            return 1
        if op in '*/':
            return 2
        return 0

    for token in tokens:
        if token.isdigit():
            output.append(token)
        elif token in '+-*/':
            # Pop operators with higher or equal precedence
            while ops and precedence(ops[-1]) >= precedence(token):
                output.append(ops.pop())
            ops.append(token)
        elif token == '(':
            ops.append(token)
        elif token == ')':
            # Pop until matching '('
            while ops and ops[-1] != '(':
                output.append(ops.pop())
            if ops and ops[-1] == '(':
                ops.pop()

    # Pop remaining operators
    while ops:
        output.append(ops.pop())

    # Evaluate postfix expression
    stack = []
    for token in output:
        if token.isdigit():
            stack.append(int(token))
        else:
            # Pop operands and apply operation
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                # Integer division truncating toward zero
                stack.append(int(a / b))

    return stack[0]

def solve(expression: str) -> int:
    def tokenize(expr):
        tokens = []
        i = 0
        n = len(expr)
        while i < n:
            if expr[i].isspace():
                i += 1
                continue

            if expr[i] in '+-*/()':
                tokens.append(expr[i])
                i += 1
            elif expr[i].isdigit():
                j = i
                while j < n and expr[j].isdigit():
                    j += 1
                num_str = expr[i:j]
                if len(num_str) > 1 and num_str[0] == '0':
                    raise ValueError("Invalid number")
                tokens.append(int(num_str))
                i = j
            else:
                raise ValueError("Invalid character")
        return tokens

    def infix_to_postfix(tokens):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        output = []
        opstack = []
        expect_operand = True

        for token in tokens:
            if isinstance(token, int):
                if not expect_operand:
                    raise ValueError("Invalid expression")
                output.append(token)
                expect_operand = False
            elif token == '(':
                if not expect_operand:
                    raise ValueError("Invalid expression")
                opstack.append(token)
                expect_operand = True
            elif token == ')':
                if expect_operand:
                    raise ValueError("Invalid expression")
                while opstack and opstack[-1] != '(':
                    output.append(opstack.pop())
                if not opstack or opstack[-1] != '(':
                    raise ValueError("Mismatched parentheses")
                opstack.pop()
                expect_operand = False
            else:
                if expect_operand:
                    if token == '+':
                        continue
                    elif token == '-':
                        output.append('u-')
                else:
                    while (opstack and opstack[-1] != '(' and
                           precedence.get(opstack[-1], 0) >= precedence.get(token, 0)):
                        output.append(opstack.pop())
                    opstack.append(token)
                expect_operand = True

        while opstack:
            op = opstack.pop()
            if op == '(':
                raise ValueError("Mismatched parentheses")
            output.append(op)

        return output

    def evaluate_postfix(tokens):
        stack = []

        for token in tokens:
            if isinstance(token, int):
                stack.append(token)
            elif token == 'u-':
                stack.append(-stack.pop())
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(int(a / b))

        return stack[0]

    return evaluate_postfix(infix_to_postfix(tokenize(expression)))

