def solve(n: int, edges: list[tuple[int, int]]) -> list[int] | None:
    if n == 0:
        return []

    # Build adjacency list and in-degree counts
    adj = [[] for _ in range(n)]
    in_degree = [0] * n

    for u, v in edges:
        if u == v:
            return None  # Self-loop creates cycle
        adj[u].append(v)
        in_degree[v] += 1

    # Min-heap for lexicographically smallest selection
    heap = []
    for i in range(n):
        if in_degree[i] == 0:
            heapq.heappush(heap, i)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    return result if len(result) == n else None

