def solve(edges, start, end):
    if start == end:
        return [0, [start]]

    # Build adjacency list
    adj = {}
    for src, dst, weight in edges:
        if src not in adj:
            adj[src] = []
        adj[src].append((dst, weight))

    # Priority queue: (total_weight, length, path, current)
    from heapq import heappush, heappop
    pq = []
    heappush(pq, (0, 0, [start], start))

    best = {}

    while pq:
        weight, length, path, current = heappop(pq)
        node = path[-1]

        if node in best:
            best_w, best_l, best_path = best[node]
            if best_w < weight or (best_w == weight and best_l < length):
                continue

        best[node] = (weight, length, path)

        if node == end:
            return [weight, path]

        if node in adj:
            for nxt, w in adj[node]:
                heappush(pq, (weight + w, length + 1, path + [nxt], nxt))

    return None

