        if node in adj:
            for neighbor, weight in adj[node]:
                new_weight = curr_weight + weight
                new_edges = curr_edges + 1
                new_path = path + [neighbor]

                if neighbor not in best or (new_weight < best[neighbor][0] or
                    (new_weight == best[neighbor][0] and new_edges < best[neighbor][1]) or
                    (new_weight == best[neighbor][0] and new_edges == best[neighbor][1] and new_path < best[neighbor][2])):
                    best[neighbor] = (new_weight, new_edges, new_path)
