def solve(grid: List[List[Optional[int]]]) -> Optional[List[int]]:
    # Handle edge cases
    if not grid or not grid[0]:
        return None
    rows, cols = len(grid), len(grid[0])
    if grid[0][0] is None or grid[rows-1][cols-1] is None:
        return None

    # DP: dp[i][j] = (min_sum, route_count, path_string)
    dp: List[List[Optional[Tuple[int, int, str]]]] = [[None] * cols for _ in range(rows)]
    dp[0][0] = (grid[0][0], 1, "")

    for i in range(rows):
        for j in range(cols):
            if dp[i][j] is None or (i == 0 and j == 0):
                continue
            best_sum = float('inf')
            best_count = 0
            best_path = ""

            # From above (down move)
            if i > 0 and dp[i-1][j] is not None:
                prev_sum, prev_count, prev_path = dp[i-1][j]
                new_sum = prev_sum + grid[i][j]
                if new_sum < best_sum:
                    best_sum = new_sum
                    best_count = prev_count
                    best_path = prev_path + "D"
                elif new_sum == best_sum:
                    best_count += prev_count
                    if prev_path + "D" < best_path:
                        best_path = prev_path + "D"

            # From left (right move)
            if j > 0 and dp[i][j-1] is not None:
                prev_sum, prev_count, prev_path = dp[i][j-1]
                new_sum = prev_sum + grid[i][j]
                if new_sum < best_sum:
                    best_sum = new_sum
                    best_count = prev_count
                    best_path = prev_path + "R"
                elif new_sum == best_sum:
                    best_count += prev_count
                    if prev_path + "R" < best_path:
                        best_path = prev_path + "R"

            dp[i][j] = (best_sum, best_count, best_path)

    return [dp[rows-1][cols-1][0], dp[rows-1][cols-1][1], dp[rows-1][cols-1][2]]

