def solve(nodes: list[str], edges: list[list[str]]) -> list[list[str]] | None:
    # Build adjacency list and indegree count
    adj = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}

    for src, dest in edges:
        if src in adj and dest in adj:  # Only if both nodes exist
            adj[src].append(dest)
            indegree[dest] += 1

    layers = []
    # Make a copy of indegree to work with
    current_indegree = indegree.copy()

    while True:
        # Find all nodes with zero indegree
        zero_nodes = [node for node in nodes if current_indegree[node] == 0]

        if not zero_nodes:
            # Check if there are remaining nodes
            remaining_nodes = [node for node in nodes if current_indegree[node] > 0]
            if remaining_nodes:
                return None
            else:
                break

        # Sort lexicographically
        zero_nodes.sort()
        layers.append(zero_nodes)

        # Remove this layer and its outgoing edges
        for node in zero_nodes:
            for neighbor in adj[node]:
                current_indegree[neighbor] -= 1

    return layers

