    # Parse pattern into tokens, handling escapes and collapsing consecutive *
    tokens = []
    i = 0
    n = len(pattern)

    while i < n:
        if pattern[i] == '\\':
            i += 1
            if i < n:
                tokens.append(pattern[i])
                i += 1
        elif pattern[i] == '*':
            # Skip all consecutive *
            while i < n and pattern[i] == '*':
                i += 1
            tokens.append('*')
        else:
            tokens.append(pattern[i])
            i += 1

    # Convert pattern to string for easier DP table indexing
    pat_str = ''.join(tokens)

    # Handle empty pattern
    if pat_str == '':
        return text == ''

    # DP table: dp[i][j] is True if pat_str[0:i] matches text[0:j]
    m, n = len(pat_str), len(text)
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    # Base case: empty pattern matches empty text
    dp[0][0] = True

    # Fill first column (empty text)
    for i in range(1, m + 1):
        if pat_str[i - 1] == '*':
            dp[i][0] = dp[i - 1][0]

    # Fill DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pat_str[i - 1] == '?':
                dp[i][j] = dp[i - 1][j - 1]
            elif pat_str[i - 1] == '*':
                # Match zero or more characters
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
            else:
                dp[i][j] = dp[i - 1][j - 1] and pat_str[i - 1] == text[j - 1]

    return dp[m][n]

