    if not 1 <= year <= 9999:
        return None
    if not 1 <= week <= 53:
        return None
    if not 1 <= weekday <= 7:
        return None

    def is_leap(y):
        return y % 400 == 0 or (y % 4 == 0 and y % 100 != 0)

    def days_in_year(y):
        return 366 if is_leap(y) else 365

    def iso_year_start_day(y):
        jan1_dow = (y + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400) % 7
        return (jan1_dow + 3) % 7

    max_week = 52
    if iso_year_start_day(year) <= 3:
        max_week = 53

    if week > max_week:
        return None

    jan1_dow = (year + (year - 1) // 4 - (year - 1) // 100 + (year - 1) // 400) % 7
    first_thursday_offset = (3 - jan1_dow) % 7
    first_thursday = 4 + first_thursday_offset

    result_day_of_year = first_thursday + (week - 1) * 7 + (weekday - 1)

    y = year
    remaining = result_day_of_year
    while remaining > days_in_year(y):
        remaining -= days_in_year(y)
        y += 1
        if not 1 <= y <= 9999:
            return None

    while remaining <= 0:
        y -= 1
        if not 1 <= y <= 9999:
            return None
        remaining += days_in_year(y)

    month_days = [0, 31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    month = 1
    for i in range(1, 13):
        if remaining <= month_days[i]:
            day = remaining
