def solve(year: int, week: int, weekday: int) -> str | None:
    if not (1 <= year <= 9999):
        return None
    if not (1 <= week <= 53):
        return None
    if not (1 <= weekday <= 7):
        return None

    # Find the Monday of ISO week 1 (the week containing January 4th)
    jan_4 = datetime(year, 1, 4)

    # Calculate days to subtract to get to Monday of that week
    # datetime.weekday() returns Monday=0, Sunday=6
    days_to_subtract = jan_4.weekday() - 0  # weekday - Monday
    if days_to_subtract < 0:
        days_to_subtract += 7

    monday_week1 = jan_4 - timedelta(days=days_to_subtract)

    # Verify that monday_week1's year is actually the given ISO year
    # If Monday of week 1 is in the previous year, then the ISO year started
    # the following year, which is not possible for a valid ISO year 1
    if monday_week1.year != year:
        return None

    # Calculate the target date
    result_date = monday_week1 + timedelta(days=(week-1)*7 + (weekday-1))

    # Validate the result is within the specified year
    if result_date.year != year:
        return None

    # Validate the result is within valid Gregorian year range
    if not (1 <= result_date.year <= 9999):
        return None

    return result_date.strftime("%Y-%m-%d")

