class CronSolver:
    def __init__(self):
        self.DAY_NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
        self.MONTH_DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    def is_leap_year(self, year: int) -> bool:
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    def days_in_month(self, year: int, month: int) -> int:
        if month == 2 and self.is_leap_year(year):
            return 29
        return self.MONTH_DAYS[month - 1]

    def get_day_of_week(self, year: int, month: int, day: int) -> int:
        # Zeller's congruence
        if month < 3:
            month += 12
            year -= 1
        k = year % 100
        j = year // 100
        h = (day + (13 * (month + 1)) // 5 + k + (k // 4) + (j // 4) + 5 * j) % 7
        # Convert from 0=Saturday to 0=Sunday
        return (h + 6) % 7

    def parse_field(self, field: str, min_val: int, max_val: int) -> Set[int]:
        result = set()
        if '/' in field:
            base, step_str = field.split('/')
            step = int(step_str)
        else:
            base = field
            step = 1

        if base == '*':
            values = range(min_val, max_val + 1)
        elif '-' in base:
            start_str, end_str = base.split('-')
            start, end = int(start_str), int(end_str)
            values = range(start, end + 1)
        else:
            values = [int(base)]

        for val in values:
            if val < min_val or val > max_val:
                continue
            if (val - min_val) % step == 0:
                result.add(val)

        return result

    def is_field_star(self, field: str) -> bool:
        return field.strip().startswith('*')

    def get_next_minute(self, expr: str, start: str) -> str:
        minute_field, hour_field, day_field, month_field, day_of_week_field = expr.split()

        minute_set = self.parse_field(minute_field, 0, 59)
        hour_set = self.parse_field(hour_field, 0, 23)
        day_of_month_set = self.parse_field(day_field, 1, 31)
        month_set = self.parse_field(month_field, 1, 12)
        day_of_week_set = self.parse_field(day_of_week_field, 0, 7)

        day_field_star = self.is_field_star(day_field)
        day_of_week_field_star = self.is_field_star(day_of_week_field)

        start_dt = datetime.strptime(start, "%Y-%m-%d %H:%M")
        current_dt = start_dt + timedelta(minutes=1)

        while True:
            year, month, day = current_dt.year, current_dt.month, current_dt.day
            hour, minute = current_dt.hour, current_dt.minute

            if minute in minute_set and hour in hour_set and month in month_set:
                day_of_week = self.get_day_of_week(year, month, day)
                dom_match = day in day_of_month_set
                dow_match = day_of_week in day_of_week_set

                if day_field_star or day_of_week_field_star:
                    if dom_match and dow_match:
                        return current_dt.strftime("%Y-%m-%d %H:%M")
                else:
                    if dom_match or dow_match:
                        return current_dt.strftime("%Y-%m-%d %H:%M")

            current_dt += timedelta(minutes=1)

