def get_field_range(field_str: str):
    """Get the min and max values for a cron field."""
    field_name = field_str.strip().split()[0] if ' ' in field_str else field_str

    ranges = {
        'minute': (0, 59),
        'hour': (0, 23),
        'day-of-month': (1, 31),
        'month': (1, 12),
        'day-of-week': (0, 7)
    }

    field_type = None
    for key in ranges:
        if key in field_str:
            field_type = key
            break

    if field_type:
        return ranges[field_type]

    return (0, 59)


def parse_cron_field(field_str: str, field_min: int, field_max: int):
    """Parse a cron field into a set of matching values."""
    items = set()
    field_str = field_str.strip()

    # Split by commas to handle multiple values
    for part in field_str.split(','):
        part = part.strip()

        if '/' in part:
            base_part, step_str = part.split('/', 1)
            step = int(step_str)

            if base_part == '*':
                values = range(field_min, field_max + 1)
            elif '-' in base_part:
                a_str, b_str = base_part.split('-', 1)
                a, b = int(a_str), int(b_str)
                values = range(a, b + 1)
            else:
                n = int(base_part)
                values = [n]

            for val in values:
                if val < field_min or val > field_max:
                    continue

                current = val
                while current <= field_max:
                    items.add(current)
                    current += step
        else:
            if part == '*':
                items.update(range(field_min, field_max + 1))
            elif '-' in part:
                a_str, b_str = part.split('-', 1)
                a, b = int(a_str), int(b_str)
                items.update(range(a, b + 1))
            else:
                n = int(part)
                if field_min <= n <= field_max:
                    items.add(n)

    return items


def increment_time(current: tuple):
    """Increment the given time by one minute."""
    year, month, day, hour, minute = current
    minute += 1

    if minute > 59:
        minute = 0
        hour += 1

    if hour > 23:
        hour = 0
        day += 1

        # Check if we need to roll over to next month
        days_in_month = get_days_in_month(year, month)
        if day > days_in_month:
            day = 1
            month += 1

            if month > 12:
                month = 1
                year += 1

    return (year, month, day, hour, minute)


def get_days_in_month(year: int, month: int):
    """Get number of days in a given month."""
    days_in_months = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    # Handle leap years
    if month == 2:
        if (year % 400 == 0) or (year % 4 == 0 and year % 100 != 0):
            return 29
        else:
            return 28

    return days_in_months[month - 1]

