        elif part == '..':
            if components and components[-1] != '..':
                components.pop()
            elif not components:
                continue
            else:
                components.append('..')
        else:
            components.append(part)
    result = ('/' + '/'.join(components) if path.startswith('/') else '/'.join(components))
