    if places >= 0:
        # Pad or truncate decimal part
        if len(dec_part) <= places:
            dec_part = dec_part.ljust(places, '0')
        else:
            # Need to round: look at digit at places+1
            round_digit = dec_part[places]
            dec_part = dec_part[:places]

            if round_digit > '5':
                # Round up
                dec_int = int(dec_part) if dec_part else 0
                dec_int += 1
                dec_part = str(dec_int)
                # Handle carry propagation
                if len(dec_part) > places:
                    dec_part = dec_part[1:]
                    int_part = str(int(int_part) + 1) if int_part else '1'
