                # Check if all following digits are zero
                if all(d == '0' for d in dec_part[places+1:]):
                    # Round to even
                    dec_int = int(dec_part) if dec_part else 0
                    if dec_int % 2 == 1:
                        dec_int += 1
                    dec_part = str(dec_int)
                    # Handle carry propagation
                    if len(dec_part) > places:
                        dec_part = dec_part[1:]
                        int_part = str(int(int_part) + 1) if int_part else '1'
                else:
                    # Round up
                    dec_int = int(dec_part) if dec_part else 0
                    dec_int += 1
                    dec_part = str(dec_int)
                    # Handle carry propagation
                    if len(dec_part) > places:
                        dec_part = dec_part[1:]
                        int_part = str(int(int_part) + 1) if int_part else '1'
        result = f"{int_part}.{dec_part}"
    else:
        # Negative places: convert to integer
        k = -places
        # Shift decimal point k places left

        # Pad int_part with leading zeroes if needed
        if len(int_part) <= k:
