        # Take last k digits from int_part
        shifted_int_part = int_part[-k:]
        # Remaining digits from int_part (if any)
        remaining_int_part = int_part[:-k] if len(int_part) > k else ''

        # Add leading zeros to shifted_int_part
        if len(shifted_int_part) < k:
            shifted_int_part = shifted_int_part.zfill(k)

        # Round: look at first digit after our target position
        if remaining_int_part:
