        # Add leading zeros to shifted_int_part
        if len(shifted_int_part) < k:
            shifted_int_part = shifted_int_part.zfill(k)

        # Round: look at first digit after our target position
        if remaining_int_part:
            round_digit = remaining_int_part[0]

            if round_digit > '5':
                # Round up
                num = int(shifted_int_part)
                num += 1
                shifted_int_part = str(num).zfill(k)

                # Handle carry propagation
                if len(shifted_int_part) > k:
                    shifted_int_part = shifted_int_part[1:]
                    if int_part:
                        int_part = str(int(int_part) + 1)
                    else:
                        int_part = '1'
                    # Need to recount remaining digits
                    if len(int_part) > k:
                        remaining_int_part = int_part[-k-1:] if len(int_part) > k else ''
                        int_part = int_part[:-k] if len(int_part) > k else ''
            elif round_digit == '5':
                # Check if all remaining digits are zero
                if all(d == '0' for d in remaining_int_part[1:]):
                    # Round to even
                    num = int(shifted_int_part)
                    if num % 2 == 1:
                        num += 1
                        shifted_int_part = str(num).zfill(k)
                        # Handle carry
                        if len(shifted_int_part) > k:
                            shifted_int_part = shifted_int_part[1:]
                            if int_part:
                                int_part = str(int(int_part) + 1)
                            else:
                                int_part = '1'
                    # else: already even, do nothing
                else:
                    # Round up
                    num = int(shifted_int_part)
                    num += 1
                    shifted_int_part = str(num).zfill(k)
                    # Handle carry
                    if len(shifted_int_part) > k:
                        shifted_int_part = shifted_int_part[1:]
                        if int_part:
                            int_part = str(int(int_part) + 1)
                        else:
                            int_part = '1'

        result = shifted_int_part if int_part else f"0{shifted_int_part}"
        # Add trailing zeroes if needed
        if k > len(result):
            result = result + '0' * (k - len(result))

    # Apply sign
    if sign and result != '0':
        result = f"{sign}{result}"
    elif sign and result == '0':
        result = '0'

    return result

def solve(value: str, places: int) -> str:
    if not value:
        return "0"

    # Parse sign and absolute value
    sign = '-' if value[0] == '-' else ''
    value = value.lstrip('+-')

    # Split into integer and fractional parts
    if '.' in value:
        int_part, frac_part = value.split('.')
    else:
        int_part, frac_part = value, ''

    # Combine all digits
    all_digits = int_part + frac_part
    int_len = len(int_part)

    # Handle negative places (round left of decimal)
    if places < 0:
        target_pos = int_len + places
        if target_pos <= 0:
            return sign + '0' + '0' * (-target_pos) if -target_pos > 0 else '0'

        # Extract digits to keep and discard
        keep_digits = all_digits[:target_pos]
        discard_digits = all_digits[target_pos:]

        # Round-half-to-even
        if len(discard_digits) > 0 and len(keep_digits) > 0:
            discard_val = int(discard_digits[0]) if len(discard_digits) > 0 else 0
            if len(keep_digits) > 0 and len(discard_digits) > 0:
                if len(discard_digits) == 1 and discard_val == 5 and len(discard_digits) == 1:
                    # Check if next digit exists and is non-zero
                    next_digit_exists = len(discard_digits) > 1 and discard_digits[1] != '0'
                    if not next_digit_exists:
                        # Exactly half - round to nearest even
                        last_keep = int(keep_digits[-1])
                        if last_keep % 2 == 1:
                            # Odd, round up
                            new_keep = str(int(keep_digits[:-1] + str(last_keep + 1)) if keep_digits[:-1] else str(last_keep + 1))
                        else:
                            # Even, keep as is
                            new_keep = keep_digits
                        keep_digits = new_keep

        # Build result
        result = keep_digits.lstrip('0')
        if not result:
            result = '0'

        return sign + result + '0' * (-places)

    # Handle positive places (round right of decimal)
    target_pos = int_len + places
    if target_pos <= int_len:
        # Round left of decimal
        keep_digits = all_digits[:target_pos]
        discard_digits = all_digits[target_pos:]

        # Round-half-to-even
        if len(discard_digits) > 0:
            if len(discard_digits) == 1 and int(discard_digits[0]) == 5:
                # Check if exactly half
                next_digit_exists = len(discard_digits) > 1 and discard_digits[1] != '0'
                if not next_digit_exists:
                    # Exactly half - round to nearest even
                    last_keep = int(keep_digits[-1]) if keep_digits else 0
                    if last_keep % 2 == 1:
                        # Odd, round up
                        new_keep = str(int(keep_digits[:-1] + str(last_keep + 1)) if keep_digits[:-1] else str(last_keep + 1))
                        keep_digits = new_keep
            elif int(discard_digits[0]) >= 5:
                # Round up
                new_keep = str(int(keep_digits + '0') + 1) if keep_digits else '1'
                keep_digits = new_keep

        # Build result
        if keep_digits:
            result = keep_digits.lstrip('0')
            if not result:
                result = '0'
        else:
            result = '0'

        return sign + result

    # Need to add fractional digits
    keep_digits = all_digits
    discard_pos = target_pos - int_len
    if discard_pos < len(frac_part):
        discard_digits = frac_part[discard_pos:]

        # Round-half-to-even
        if len(discard_digits) > 0:
            if len(discard_digits) == 1 and int(discard_digits[0]) == 5:
                # Check if exactly half
                next_digit_exists = len(discard_digits) > 1 and discard_digits[1] != '0'
                if not next_digit_exists:
                    # Exactly half - round to nearest even
                    last_keep = int(keep_digits[-1]) if keep_digits else 0
                    if last_keep % 2 == 1:
                        # Odd, round up
                        new_keep = str(int(keep_digits[:-1] + str(last_keep + 1)) if keep_digits[:-1] else str(last_keep + 1))
                        keep_digits = new_keep
            elif int(discard_digits[0]) >= 5:
                # Round up
                new_keep = str(int(keep_digits + '0') + 1) if keep_digits else '1'
                keep_digits = new_keep

        # Add necessary fractional digits
        while len(keep_digits) < target_pos:
            keep_digits += '0'

    # Build result
    if '.' in value:
        int_result = keep_digits[:int_len].lstrip('0')
        if not int_result:
            int_result = '0'
        frac_result = keep_digits[int_len:]

        return sign + int_result + '.' + frac_result
    else:
        result = keep_digits.lstrip('0')
        if not result:
            result = '0'
        return sign + result

