    def parse_version(version: str):
        # Split core, prerelease, and build
        if '+' in version:
            core_part, build = version.split('+', 1)
        else:
            core_part, build = version, None

        # Check for prerelease
        parts = core_part.split('-')
        core = parts[0]
        prerelease = parts[1] if len(parts) > 1 else None

        # Parse core numbers
        major, minor, patch = map(int, core.split('.'))

        # Parse prerelease identifiers
        prerelease_ids = []
        if prerelease:
            for ident in prerelease.split('.'):
                if ident.isdigit():
                    prerelease_ids.append((0, int(ident)))
                else:
                    prerelease_ids.append((1, ident))

        return {
            'original': version,
            'core': (major, minor, patch),
            'prerelease': prerelease_ids,
            'build': build
        }

    def compare_versions(v1: dict, v2: dict):
        # Compare core numbers
        if v1['core'] < v2['core']:
            return -1
        if v1['core'] > v2['core']:
            return 1

        # Same core, compare prerelease
        pr1, pr2 = v1['prerelease'], v2['prerelease']

        # Release ranks above prerelease
        if not pr1 and pr2:
            return 1
        if pr1 and not pr2:
            return -1

        # Both have prerelease or both don't
        # Compare prerelease identifiers
        for i in range(min(len(pr1), len(pr2))):
            type1, val1 = pr1[i]
            type2, val2 = pr2[i]

            if type1 != type2:
                # Numeric is lower than nonnumeric
                return -1 if type1 < type2 else 1

            if type1 == 0:  # Both numeric
                if val1 != val2:
                    return -1 if val1 < val2 else 1
            else:  # Both nonnumeric
                if val1 != val2:
                    return -1 if val1 < val2 else 1

        # All matched so far, shorter prerelease ranks lower
        if len(pr1) < len(pr2):
            return -1
        if len(pr1) > len(pr2):
            return 1

        return 0

    # Parse all versions
    parsed = [parse_version(v) for v in versions]

    # Sort using SemVer comparison (maintaining stability for equal precedence)
    def sort_key(idx):
        return tuple(
            compare_versions(parsed[idx], parsed[i])
            for i in range(len(parsed))
        )

    # Since sort_key needs to be comparable, we'll use a custom approach
    # We'll use a stable sort with a custom comparator using functools.cmp_to_key
    from functools import cmp_to_key

    sorted_indices = sorted(
        range(len(parsed)),
        key=cmp_to_key(lambda i, j: compare_versions(parsed[i], parsed[j]))
    )

    # Return versions in sorted order
    return [versions[i] for i in sorted_indices]

