def _parse_quoted_field(text: str, start: int) -> tuple[str, int]:
    """Parse a quoted field starting at start index.
    Returns the unescaped field content and the index after the closing quote."""
    content = []
    i = start + 1  # Skip opening quote

    while i < len(text):
        if text[i] == '"':
            if i + 1 < len(text) and text[i + 1] == '"':
                # Escaped quote
                content.append('"')
                i += 2
            else:
                # Closing quote
                i += 1
                break
        else:
            content.append(text[i])
            i += 1

    return ''.join(content).replace('""', '"'), i


