            if line[i] == '"':
                content, next_pos = _parse_quoted_field(line, i)
                fields.append(content)
                field_start = next_pos
                i = next_pos
                if i < len(line) and line[i] == ',':
                    i += 1
            elif line[i] == ',':
                fields.append(line[field_start:i])
                field_start = i + 1
                i += 1
            else:
                i += 1

        if field_start < len(line):
            field = line[field_start:]
            if field.startswith('"'):
                content, _ = _parse_quoted_field(field, 0)
                fields.append(content)
            else:
                fields.append(field)
        elif field_start == len(line) and line and line[-1] == ',':
            # Last char is ',', add empty final field
            fields.append('')

        result.append(fields)

    return result

