                i += 1
    if i < len(numeral):
        if numeral[i] == 'I' and i + 1 < len(numeral) and numeral[i + 1] == 'X':
            units = 'IX'
            i += 2
        elif numeral[i] == 'V':
            units = 'V'
            i += 1
        elif numeral[i] == 'I' and i + 1 < len(numeral) and numeral[i + 1] == 'V':
            units = 'IV'
            i += 2
        else:
            while i < len(numeral) and numeral[i] == 'I':
                units += 'I'
                i += 1

    if i != len(numeral):
        return False

    expected = ''
    expected += 'M' * (total // 1000)

    hundreds_digit = (total % 1000) // 100
    if hundreds_digit == 9:
        expected += 'CM'
    elif hundreds_digit == 5:
        expected += 'D'
    elif hundreds_digit == 4:
        expected += 'CD'
    elif hundreds_digit >= 1:
        expected += 'C' * hundreds_digit

