    if units_digit == 9:
        expected += 'IX'
    elif units_digit == 5:
        expected += 'V'
    elif units_digit == 4:
        expected += 'IV'
    elif units_digit >= 1:
        expected += 'I' * units_digit

    return expected == numeral

