    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    def _lcm(a: int, b: int) -> int:
        return a // _gcd(a, b) * b

    if not congruences:
        return [0, 1]

    # Normalize remainders
    for i, (rem, mod) in enumerate(congruences):
        if mod <= 0:
            return None
        congruences[i][0] = rem % mod

    r, m = congruences[0]

    for i in range(1, len(congruences)):
        a, n = congruences[i]
        g = _gcd(m, n)

        # Check consistency
        if (a - r) % g != 0:
            return None

        # Find solution
        p, q = m // g, n // g
        # Find inverse of p modulo q
        inv = pow(p, -1, q)
        k = ((a - r) // g * inv) % q
        r = r + m * k
        m = _lcm(m, n)
        r %= m

    return [r, m]

