        # Find x such that a*x ≡ 1 (mod m)
        # Using extended Euclidean algorithm
        if m == 1:
            return 0

        original_m = m
        x0, x1 = 1, 0

        while m > 0:
            q = a // m
            a, m, x0, x1 = m, a - q * m, x1, x0 - q * x1

        if a != 1:
            return None  # No inverse exists

        return x0 % original_m

