    M = 1
    for _, mod in normalized:
        M = lcm(M, mod)

    # Solve using CRT
    x = 0
    for rem, mod in normalized:
        Mi = M // mod
        Mi_inv = mod_inverse(Mi % mod, mod)

        if Mi_inv is None:
            # This shouldn't happen for valid inputs with M being LCM
            return None

        x += rem * Mi * Mi_inv

    # Reduce modulo M
    x %= M

    return [x, M]

