def solve(capacity: int, operations: list[list]) -> list[list]:
    if capacity < 0:
        raise ValueError("Capacity must be non-negative")

    cache = {}
    keys_order = []
    get_results = []

    for op in operations:
        if op[0] == "put":
            key, value = op[1], op[2]

            if key in cache:
                keys_order.remove(key)
            else:
                if len(keys_order) >= capacity and capacity > 0:
                    lru_key = keys_order.pop(0)
                    del cache[lru_key]

