            keys_order.append(key)

        elif op[0] == "get":
            key = op[1]
            if key in cache:
                get_results.append(cache[key])
                keys_order.remove(key)
                keys_order.append(key)
            else:
                get_results.append(None)

        elif op[0] == "delete":
            key = op[1]
            if key in cache:
                del cache[key]
                keys_order.remove(key)

