    best_a = 0
    best_b = 1
    best_dist = abs(0 - numerator)

    for b in range(1, max_denominator + 1):
        lower_a = (numerator * b) // denominator
        upper_a = lower_a + 1

        for a in (lower_a, upper_a):
            if a < 0:
