def solve(operations):
    stack = []
    pop_results = []
    history = []

    for op in operations:
        if op[0] == "push":
            stack.append(op[1])
        elif op[0] == "pop":
            value = stack.pop()
            pop_results.append(value)
        elif op[0] == "dup":
            stack.append(stack[-1])
        elif op[0] == "swap":
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op[0] == "add":
            top = stack.pop()
            second = stack.pop()
            stack.append(second + top)
        elif op[0] == "sub":
            top = stack.pop()
            second = stack.pop()
            stack.append(second - top)
        elif op[0] == "begin":
            history.append((list(stack), list(pop_results)))
        elif op[0] == "commit":
            history.pop()
        elif op[0] == "rollback":
            stack, pop_results = history.pop()

    return [stack, pop_results]

