def solve(operations: list[list]) -> list[list[int]]:
    stack = []
    pop_results = []
    transaction_stack = []

    for op in operations:
        op_type = op[0]

        if op_type == "push":
            stack.append(op[1])
        elif op_type == "pop":
            value = stack.pop()
            pop_results.append(value)
        elif op_type == "dup":
            stack.append(stack[-1])
        elif op_type == "swap":
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op_type == "add":
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif op_type == "sub":
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif op_type == "begin":
            transaction_stack.append((stack.copy(), pop_results.copy()))
        elif op_type == "commit":
            transaction_stack.pop()
        elif op_type == "rollback":
            if transaction_stack:
                stack, pop_results = transaction_stack.pop()

    return [stack, pop_results]

