    # Calculate UTF-16 length by summing units per character
    utf16_length = 0
    for char in text:
        code = ord(char)
        if code <= 0xFFFF:
            utf16_length += 1
        else:
            utf16_length += 2

    # Process each offset
    for offset in offsets:
        # Handle invalid offsets
        if offset < 0 or offset > utf16_length:
            result.append(None)
            continue

        # Find Python index at this UTF-16 boundary
        utf16_so_far = 0
        for i, char in enumerate(text):
            code = ord(char)
            char_len = 1 if code <= 0xFFFF else 2

            # Check if offset is at the boundary of this character
            if utf16_so_far + char_len == offset:
                result.append(i)
                break
            # If offset falls inside this character's units
            elif utf16_so_far < offset < utf16_so_far + char_len:
                result.append(None)
                break

            utf16_so_far += char_len
        else:
            # Offset is at the very end (equal to utf16_length)
            if offset == utf16_length:
                result.append(len(text))

    return result

